// Picks the WebP variant of a photo for <picture>, but ONLY if that file really exists.
// (A <source> pointing at a missing file would show a broken image instead of falling back to the JPG.)
// Variants are generated by scripts/optimize-images.mjs.
import { existsSync } from 'node:fs';

const PHOTO = /^\/images\/photos\/([^/]+)\.jpe?g$/i;

export function photoWebp(src, { thumb = false } = {}) {
  const m = typeof src === 'string' ? src.match(PHOTO) : null;
  if (!m) return null;
  const variant = thumb ? `/images/photos/thumbs/${m[1]}.webp` : `/images/photos/${m[1]}.webp`;
  return existsSync(`public${variant}`) ? variant : null;
}
